// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url: pw('paperless_url'),
    alarm_email:   pw('mail_betrieb'),
    absender:      pw('mail_absender'),

    // ── fachlich, hier zu pflegen ──
    // heartbeat_wochentag: 0=So … 6=Sa; an diesem Tag kommt IMMER eine
    //   Status-Mail (auch ohne Probleme). -1 = nie.
    // task_stau_minuten: ab wann eine hängende Aufgabe als Stau gilt.
    heartbeat_wochentag: 1,
    task_stau_minuten: 60
  }
}];

// Ergebnisse auswerten und entscheiden, ob eine Mail rausgeht.
const cfg = $('Konfiguration').first().json;
const stats = $('Statistik laden').first().json ?? {};
const taskItems = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length > 0);

const probleme = [];

// 1) API erreichbar? statistics liefert u. a. documents_total.
const apiOk = typeof stats.documents_total === 'number';
if (!apiOk) {
  const detail = stats.error ? String(stats.error.message ?? JSON.stringify(stats.error)).slice(0, 200) : 'unerwartete Antwort';
  probleme.push('Paperless-API nicht erreichbar (' + cfg.paperless_url + '): ' + detail);
}

// 2) + 3) Tasks auswerten, nur sinnvoll, wenn der Task-Abruf selbst geklappt hat.
// check_sanity-Tasks (Paperless' periodischer Konsistenz-Check) sind KEINE
// Dokumentenverarbeitungen: kein Dateibezug, laufen wiederkehrend gegen den
// immer gleichen Zustand und lassen sich nicht durch "quittieren" beheben.
// Deshalb getrennt von echten Verarbeitungsfehlern behandelt: eigene,
// unauffällige Rubrik statt Alarm, lösen für sich allein keine Mail aus.
let failed = [];
let sanity = [];
let stau = [];
const tasksFehler = taskItems.length === 1 && taskItems[0].error;
if (tasksFehler) {
  if (apiOk) probleme.push('Task-Status nicht abrufbar: ' + String(taskItems[0].error.message ?? '').slice(0, 200));
} else {
  const offen = taskItems.filter(t => t.status === 'FAILURE' && !t.acknowledged);
  failed = offen.filter(t => t.task_name !== 'check_sanity');
  sanity = offen.filter(t => t.task_name === 'check_sanity');
  const cutoff = Date.now() - cfg.task_stau_minuten * 60000;
  stau = taskItems.filter(t => ['PENDING', 'STARTED'].includes(t.status) && t.date_created && new Date(t.date_created).getTime() < cutoff);
  if (failed.length) probleme.push(failed.length + ' fehlgeschlagene Verarbeitung(en), Details siehe Tabelle unten.');
  if (stau.length) probleme.push(stau.length + ' Task(s) hängen seit über ' + cfg.task_stau_minuten + ' Minuten in der Warteschlange (Verarbeitungs-Stau?).');
}

// Heartbeat: Wochentag zuverlässig in Europe/Berlin bestimmen (Server-TZ egal).
const wdShort = new Intl.DateTimeFormat('en-US', { weekday: 'short', timeZone: 'Europe/Berlin' }).format(new Date());
const wochentag = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[wdShort];
const heartbeat = wochentag === cfg.heartbeat_wochentag;
const senden = probleme.length > 0 || heartbeat;

// Mail aufbauen.
const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const problemHtml = probleme.length
  ? '<ul style="color:#c0392b;font-weight:bold;">' + probleme.map(p => '<li>' + esc(p) + '</li>').join('') + '</ul>'
  : '<p style="color:#27ae60;font-weight:bold;">Alle Prüfungen bestanden ✓</p>';

let failedHtml = '';
if (failed.length) {
  const rows = failed.slice(0, 20).map(t => '<tr>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;">' + esc(t.task_file_name || t.task_id || '?') + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;font-size:12px;">' + esc(String(t.result ?? '').slice(0, 200)) + '</td>'
    + '</tr>').join('\n');
  failedHtml = '<h3 style="color:#2c3e50;">Fehlgeschlagene Verarbeitungen</h3>'
    + '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;width:100%;margin:8px 0;">'
    + '<thead><tr style="background:#2c3e50;color:#fff;"><th style="padding:8px 12px;text-align:left;">Datei</th><th style="padding:8px 12px;text-align:left;">Fehler</th></tr></thead>'
    + '<tbody>' + rows + '</tbody></table>'
    + '<p style="font-size:12px;color:#555;">Sichtbar auch unter Einstellungen → Systemstatus in Paperless.</p>';
}

let sanityHtml = '';
if (sanity.length) {
  sanityHtml = '<p style="font-size:12px;color:#888;margin-top:16px;border-top:1px solid #eee;padding-top:8px;">'
    + 'ℹ️ ' + sanity.length + ' Hinweis(e) vom internen Konsistenz-Check (check_sanity): '
    + 'kein Verarbeitungsfehler, kein Handlungsbedarf durch dieses Mail. Details: Einstellungen → Systemstatus in Paperless.'
    + '</p>';
}

const statusHtml = apiOk
  ? '<p style="font-size:14px;">Dokumente gesamt: <strong>' + stats.documents_total + '</strong> · davon in der Inbox: <strong>' + (stats.documents_inbox ?? '-') + '</strong></p>'
  : '';

const html = '<div style="font-family:Arial,sans-serif;max-width:750px;">'
  + '<h2 style="color:#2c3e50;border-bottom:2px solid #2c3e50;padding-bottom:8px;">Paperless-Health-Check</h2>'
  + problemHtml + statusHtml + failedHtml + sanityHtml
  + '<p style="color:#95a5a6;font-size:12px;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">Geprüft am ' + now + ' · <a href="https://github.com/paper-werk">Paper-Werk</a></p>'
  + '</div>';

const subject = probleme.length
  ? '🔴 Paperless-Health: ' + probleme.length + ' Problem(e)'
  : '🟢 Paperless-Health: alles in Ordnung';

return [{ json: { senden, subject, html, toEmail: cfg.alarm_email, fromEmail: cfg.absender, probleme } }];
